const input = $input.first()?.json ?? {};
const output = { event: 'cherry.weekly_repo_digest', source: 'manual', repo: 'div0rce/cherry', timestamp: input.timestamp ?? new Date().toISOString(), payload: input, workflow: '08_repo_intelligence_digest', ok: true, status: 'accepted', summary: 'Scheduled cherry.weekly_repo_digest started.', actions: [] };
return [{ json: output }];

const event = $input.first()?.json ?? {};
const fields = ["repo"];
const missing = fields.filter((field) => field.split('.').reduce((value, key) => value?.[key], event) === undefined);
const output = { ...event, valid: missing.length === 0, validationErrors: missing, status: missing.length === 0 ? event.status : 'failed', summary: missing.length === 0 ? event.summary : 'Payload missing required fields: ' + missing.join(', ') };
return [{ json: output }];

const event = $input.first()?.json ?? {};
const output = { ...event, workflow: event.workflow ?? '08_repo_intelligence_digest', sinkRouting: {
  discord: '{{ $env.DISCORD_WEBHOOK_URL }}', slack: '{{ $env.SLACK_WEBHOOK_URL }}', email: '{{ $env.EMAIL_WEBHOOK_URL }}', notion: '{{ $env.NOTION_WEBHOOK_URL }}', googleSheets: '{{ $env.GOOGLE_SHEETS_WEBHOOK_URL }}', linearJira: '{{ $env.LINEAR_JIRA_WEBHOOK_URL }}', githubProjects: '{{ $env.GITHUB_PROJECTS_WEBHOOK_URL }}', archive: '{{ $env.CHERRY_API_BASE_URL }}/api/automation/events', incidentTimeline: '{{ $env.CHERRY_API_BASE_URL }}/api/automation/incident-timeline' } };
return [{ json: output }];

const event = $input.first()?.json ?? {};
const output = { ok: event.ok !== false, workflow: event.workflow, status: event.status ?? 'accepted', summary: event.summary ?? 'Weekly repo digest completed.', actions: event.actions ?? [] };
return [{ json: output }];
